import { Component, OnInit } from '@angular/core';

interface LetterItem {
  letter: string;
  name: string;
  example: string;
  exampleMeaning: string;
  category: 'vowel' | 'consonant';
  forms: string[];
}

@Component({
  selector: 'app-alphabet',
  templateUrl: './alphabet.component.html',
  styleUrls: ['./alphabet.component.scss']
})
export class AlphabetComponent implements OnInit {

  searchQuery = '';
  selectedFilter: 'all' | 'vowel' | 'consonant' = 'all';

  letters: LetterItem[] = [
    { letter: 'آ - ا', name: 'الف', example: 'آب، انار', exampleMeaning: 'آب زلال، انار شیرین', category: 'vowel', forms: ['آ اول', 'ا غیر اول'] },
    { letter: 'ب', name: 'بِ', example: 'باران، سیب', exampleMeaning: 'باران بهاری، سیب سرخ', category: 'consonant', forms: ['بـ اول', 'ـبـ وسط', 'ـب آخر چسبان', 'ب آخر تنها'] },
    { letter: 'پ', name: 'پِ', example: 'پرنده، توپ', exampleMeaning: 'پرنده زیبا، توپ بازی', category: 'consonant', forms: ['پـ اول', 'ـپـ وسط', 'ـپ آخر چسبان', 'پ آخر تنها'] },
    { letter: 'ت', name: 'تِ', example: 'توت، درخت', exampleMeaning: 'توت شیرین، درخت سرسبز', category: 'consonant', forms: ['تـ اول', 'ـتـ وسط', 'ـت آخر چسبان', 'ت آخر تنها'] },
    { letter: 'ث', name: 'ثِ', example: 'ثریا، مثلث', exampleMeaning: 'آسمان و ستاره، شکل مثلث', category: 'consonant', forms: ['ثـ اول', 'ـثـ وسط', 'ـث آخر چسبان', 'ث آخر تنها'] },
    { letter: 'ج', name: 'جیم', example: 'جنگل، کاج', exampleMeaning: 'جنگل سرسبز، درخت کاج', category: 'consonant', forms: ['جـ اول', 'ـجـ وسط', 'ـج آخر چسبان', 'ج آخر تنها'] },
    { letter: 'چ', name: 'چِه', example: 'چتر، قارچ', exampleMeaning: 'چتر بارانی، قارچ سفید', category: 'consonant', forms: ['چـ اول', 'ـچـ وسط', 'ـچ آخر چسبان', 'چ آخر تنها'] },
    { letter: 'ح', name: 'حا', example: 'حوله، تمساح', exampleMeaning: 'حوله نرم، تمساح بزرگ', category: 'consonant', forms: ['حـ اول', 'ـحـ وسط', 'ـح آخر چسبان', 'ح آخر تنها'] },
    { letter: 'خ', name: 'خِ', example: 'خرگوش، شاخه', exampleMeaning: 'خرگوش ناز، شاخه گل', category: 'consonant', forms: ['خـ اول', 'ـخـ وسط', 'ـخ آخر چسبان', 'خ آخر تنها'] },
    { letter: 'د', name: 'دال', example: 'دست، باد', exampleMeaning: 'دست مهربان، باد خنک', category: 'consonant', forms: ['د تنها', 'ـد چسبان'] },
    { letter: 'ذ', name: 'ذال', example: 'ذرت، لذت', exampleMeaning: 'بلال و ذرت، لذت درس', category: 'consonant', forms: ['ذ تنها', 'ـذ چسبان'] },
    { letter: 'ر', name: 'رِ', example: 'رنگین‌کمان، بهار', exampleMeaning: 'رنگین‌کمان هفت‌رنگ', category: 'consonant', forms: ['ر تنها', 'ـر چسبان'] },
    { letter: 'ز', name: 'زِ', example: 'زنبور، موز', exampleMeaning: 'زنبور عسل، موز زرد', category: 'consonant', forms: ['ز تنها', 'ـز چسبان'] },
    { letter: 'ژ', name: 'ژِ', example: 'ژاله، مژده', exampleMeaning: 'گل و شبنم، خبر خوش', category: 'consonant', forms: ['ژ تنها', 'ـژ چسبان'] },
    { letter: 'س', name: 'سین', example: 'سیب، یاس', exampleMeaning: 'سیب سرخ، گل یاس', category: 'consonant', forms: ['سـ اول', 'ـسـ وسط', 'ـس آخر چسبان', 'س آخر تنها'] },
    { letter: 'ش', name: 'شین', example: 'شیر، خورشید', exampleMeaning: 'شیر جنگل، خورشید تابان', category: 'consonant', forms: ['شـ اول', 'ـشـ وسط', 'ـش آخر چسبان', 'ش آخر تنها'] },
    { letter: 'ص', name: 'صاد', example: 'صابون، قرص', exampleMeaning: 'صابون معطر، قرص ماه', category: 'consonant', forms: ['صـ اول', 'ـصـ وسط', 'ـص آخر چسبان', 'ص آخر تنها'] },
    { letter: 'ض', name: 'ضاد', example: 'ضامن، حوض', exampleMeaning: 'ضامن آهو، حوض کاشی', category: 'consonant', forms: ['ضـ اول', 'ـضـ وسط', 'ـض آخر چسبان', 'ض آخر تنها'] },
    { letter: 'ط', name: 'طا', example: 'طوطی، خط', exampleMeaning: 'طوطی سخنگو، خط زیبا', category: 'consonant', forms: ['ط اول و تنها', 'ـطـ وسط و چسبان'] },
    { letter: 'ظ', name: 'ظا', example: 'ظرف، نظم', exampleMeaning: 'ظرف چینی، نظم کلاس', category: 'consonant', forms: ['ظ اول و تنها', 'ـظـ وسط و چسبان'] },
    { letter: 'ع', name: 'عین', example: 'عینک، شمع', exampleMeaning: 'عینک مطالعه، نور شمع', category: 'consonant', forms: ['عـ اول', 'ـعـ وسط', 'ـع آخر چسبان', 'ع آخر تنها'] },
    { letter: 'غ', name: 'غین', example: 'غار، کلاغ', exampleMeaning: 'غار پر رمز و راز، کلاغ باهوش', category: 'consonant', forms: ['غـ اول', 'ـغـ وسط', 'ـغ آخر چسبان', 'غ آخر تنها'] },
    { letter: 'ف', name: 'فِ', example: 'فندق، کیف', exampleMeaning: 'فندق خوشمزه، کیف مدرسه', category: 'consonant', forms: ['فـ اول', 'ـفـ وسط', 'ـف آخر چسبان', 'ف آخر تنها'] },
    { letter: 'ق', name: 'قاف', example: 'قایق، قوری', exampleMeaning: 'قایق چوبی، قوری چای', category: 'consonant', forms: ['قـ اول', 'ـقـ وسط', 'ـق آخر چسبان', 'ق آخر تنها'] },
    { letter: 'ک', name: 'کاف', example: 'کتاب، بادکنک', exampleMeaning: 'کتاب قصه، بادکنک رنگی', category: 'consonant', forms: ['کـ اول', 'ـکـ وسط', 'ـک آخر چسبان', 'ک آخر تنها'] },
    { letter: 'گ', name: 'گاف', example: 'گل، گرگ', exampleMeaning: 'گل خوشبو، گرگ خاکستری', category: 'consonant', forms: ['گـ اول', 'ـگـ وسط', 'ـگ آخر چسبان', 'گ آخر تنها'] },
    { letter: 'ل', name: 'لام', example: 'لیمو، گل', exampleMeaning: 'لیموی ترش، شاخه گل', category: 'consonant', forms: ['لـ اول', 'ـلـ وسط', 'ـل آخر چسبان', 'ل آخر تنها'] },
    { letter: 'م', name: 'میم', example: 'مادر، بادام', exampleMeaning: 'مادر مهربان، بادام تازه', category: 'consonant', forms: ['مـ اول', 'ـمـ وسط', 'ـم آخر چسبان', 'م آخر تنها'] },
    { letter: 'ن', name: 'نون', example: 'نان، باران', exampleMeaning: 'نان گرم، باران بهاری', category: 'consonant', forms: ['نـ اول', 'ـنـ وسط', 'ـن آخر چسبان', 'ن آخر تنها'] },
    { letter: 'و', name: 'واو', example: 'ورزش، ابرو', exampleMeaning: 'ورزش صبحگاهی، ابرو', category: 'vowel', forms: ['و تنها', 'ـو چسبان'] },
    { letter: 'ه', name: 'هـِ', example: 'هواپیما، ماه', exampleMeaning: 'هواپیمای تندرو، ماه تابان', category: 'consonant', forms: ['هـ اول', 'ـهـ وسط', 'ـه آخر چسبان', 'ه آخر تنها'] },
    { letter: 'ی', name: 'یِ', example: 'یاس، ماهی', exampleMeaning: 'گل یاس، ماهی قرمز', category: 'vowel', forms: ['یـ اول', 'ـیـ وسط', 'ـی آخر چسبان', 'ی آخر تنها'] },
  ];

  selectedLetter: LetterItem = this.letters[0];

  // تمرین حدس نشانه
  quizCurrentIndex = 0;
  quizScore = 0;
  quizAnswered = false;
  quizSelectedOption = '';
  quizIsCorrect = false;
  quizOptions: string[] = [];

  ngOnInit(): void {
    this.generateQuizQuestion();
  }

  get filteredLetters(): LetterItem[] {
    return this.letters.filter(item => {
      const matchSearch = !this.searchQuery ||
        item.letter.includes(this.searchQuery) ||
        item.name.includes(this.searchQuery) ||
        item.example.includes(this.searchQuery);

      const matchCategory = this.selectedFilter === 'all' || item.category === this.selectedFilter;
      return matchSearch && matchCategory;
    });
  }

  selectLetter(item: LetterItem): void {
    this.selectedLetter = item;
  }

  generateQuizQuestion(): void {
    this.quizAnswered = false;
    this.quizSelectedOption = '';
    const randomIdx = Math.floor(Math.random() * this.letters.length);
    this.quizCurrentIndex = randomIdx;
    const target = this.letters[randomIdx];

    // Pick 3 random distractors
    const distractors = this.letters
      .filter((_, i) => i !== randomIdx)
      .sort(() => 0.5 - Math.random())
      .slice(0, 3)
      .map(x => x.name);

    this.quizOptions = [target.name, ...distractors].sort(() => 0.5 - Math.random());
  }

  answerQuiz(opt: string): void {
    if (this.quizAnswered) { return; }
    this.quizSelectedOption = opt;
    this.quizAnswered = true;
    const current = this.letters[this.quizCurrentIndex];
    if (opt === current.name) {
      this.quizIsCorrect = true;
      this.quizScore += 10;
    } else {
      this.quizIsCorrect = false;
    }
  }

  playAudioSynthesis(text: string): void {
    if ('speechSynthesis' in window) {
      const utterance = new SpeechSynthesisUtterance(text);
      utterance.lang = 'fa-IR';
      window.speechSynthesis.speak(utterance);
    }
  }
}
